+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+/**
+ * A form for sending a message, and a list of the messages sent so far.
+ */
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final String NAME_REQUIRED = "Name is required";
+    static final String EMAIL_INVALID = "Enter a valid e-mail address";
+    static final String EMAIL_OR_PHONE_REQUIRED = "Give an e-mail address or a phone number";
+    static final String MESSAGE_REQUIRED = "Message is required";
+    static final String MESSAGE_TOO_LONG = "Message must be at most 500 characters";
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL_PATTERN = Pattern
+            .compile(EmailValidator.PATTERN);
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final List<TextFieldBase<?, String>> fields = List.of(name, email,
+            phone, message);
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> sentMessages = new Grid<>();
+
+    /** True while the form is being emptied by the application itself. */
+    private boolean clearingForm;
+
+    private Dialog leaveDialog;
+
+    public ContactView() {
+        setWidthFull();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                createForm(), createSentMessages());
+
+        send.addClickListener(event -> trySend());
+        // Enter anywhere in the view sends the message as well.
+        send.addClickShortcut(Key.ENTER);
+    }
+
+    private FormLayout createForm() {
+        message.setHeight("8em");
+        fields.forEach(this::configure);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.setEnabled(true);
+
+        FormLayout form = new FormLayout();
+        form.setMaxWidth("40em");
+        form.add(name, email, phone, message);
+        form.setColspan(message, 2);
+        form.add(new HorizontalLayout(send));
+        return form;
+    }
+
+    private void configure(TextFieldBase<?, String> field) {
+        // The form is validated when Send is pressed, not while typing, so the
+        // built-in validation is turned off and the fields are marked invalid
+        // by this view only.
+        field.setManualValidation(true);
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.addValueChangeListener(event -> onFieldEdited());
+    }
+
+    private Grid<ContactMessage> createSentMessages() {
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name")
+                .setKey("name").setAutoWidth(true).setFlexGrow(0);
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message")
+                .setKey("message");
+        sentMessages.setAllRowsVisible(true);
+        sentMessages.setWidthFull();
+        return sentMessages;
+    }
+
+    @Override
+    protected void onAttach(AttachEvent attachEvent) {
+        super.onAttach(attachEvent);
+        refreshSentMessages();
+    }
+
+    private void onFieldEdited() {
+        if (!clearingForm) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void trySend() {
+        if (!send.isEnabled() || !isValid()) {
+            return;
+        }
+
+        ContactMessage sent = new ContactMessage(value(name), value(email),
+                value(phone), value(message), Instant.now());
+        MessageStore.current().add(sent);
+        refreshSentMessages();
+
+        Notification.show("Message sent");
+
+        clearForm();
+        send.setEnabled(false);
+    }
+
+    /**
+     * Validates the form, marking every field that fails a rule as invalid.
+     *
+     * @return true when the form can be sent
+     */
+    private boolean isValid() {
+        clearErrors();
+
+        boolean valid = true;
+
+        if (value(name).isBlank()) {
+            markInvalid(name, NAME_REQUIRED);
+            valid = false;
+        }
+
+        String emailValue = value(email);
+        String phoneValue = value(phone);
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue)
+                .matches()) {
+            markInvalid(email, EMAIL_INVALID);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, EMAIL_OR_PHONE_REQUIRED);
+            valid = false;
+        }
+
+        String messageValue = message.getValue() == null ? ""
+                : message.getValue();
+        if (messageValue.isBlank()) {
+            markInvalid(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        fields.forEach(field -> {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        });
+    }
+
+    private void clearForm() {
+        clearingForm = true;
+        try {
+            fields.forEach(HasValue::clear);
+            clearErrors();
+        } finally {
+            clearingForm = false;
+        }
+    }
+
+    private void refreshSentMessages() {
+        sentMessages.setItems(MessageStore.current().newestFirst());
+    }
+
+    private static String value(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+
+    private boolean hasContent() {
+        return fields.stream().map(HasValue::getValue)
+                .anyMatch(value -> value != null && !value.isEmpty());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasContent()) {
+            return;
+        }
+        ContinueNavigationAction action = event.postpone();
+        openLeaveDialog(action);
+    }
+
+    private void openLeaveDialog(ContinueNavigationAction action) {
+        if (leaveDialog != null) {
+            leaveDialog.close();
+        }
+
+        Dialog dialog = new Dialog();
+        leaveDialog = dialog;
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.setHeaderTitle("Your message has not been sent");
+        dialog.add(new Paragraph(
+                "If you leave now, what you have written is lost."));
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            leaveDialog = null;
+        });
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            leaveDialog = null;
+            clearForm();
+            action.proceed();
+        });
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+
+        HorizontalLayout buttons = new HorizontalLayout(keepEditing, discard);
+        dialog.add(buttons);
+        dialog.open();
+    }
+}
