+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ * <p>
+ * The store outlives a single visit to the contact view: it lives in the Vaadin
+ * session, so navigating away and back still shows everything that was sent.
+ * Nothing is written to disk.
+ */
+public class MessageStore implements Serializable {
+
+    /** Used when there is no Vaadin session, e.g. in plain unit tests. */
+    private static final MessageStore FALLBACK = new MessageStore();
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    /**
+     * The store of the current session, created on first use.
+     */
+    public static MessageStore current() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            return FALLBACK;
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+
+    /**
+     * Adds a message as the newest one.
+     */
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    /**
+     * All messages sent so far, newest first.
+     */
+    public synchronized List<ContactMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
