+
+        aboutLink().click();
+        waitForVaadin();
+        assertThat(page.locator("h1")).hasText("About");
+
+        page.goBack();
+        waitForVaadin();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void aboutLink_navigatesWithoutReloadingThePage() {
+        page.evaluate("() => window.__notReloaded = true");
+
+        aboutLink().click();
+        waitForVaadin();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertEquals(Boolean.TRUE, page.evaluate("() => window.__notReloaded"),
+                "the page was reloaded");
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        aboutLink().click();
+        waitForVaadin();
+
+        assertFalse(dialogButton("Keep editing").isVisible(), "no dialog");
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void filledForm_keepEditing_staysOnTheView() {
+        name().setValue("Alice");
+        waitForVaadin();
+        aboutLink().click();
+        waitForVaadin();
+
+        assertThat(dialogButton("Keep editing")).isVisible();
+        dialogButton("Keep editing").click();
+        waitForVaadin();
+
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals("Alice", name().getValue());
+        assertThat(dialogButton("Keep editing")).isHidden();
+    }
+
+    @Test
+    void filledForm_discard_leavesTheView() {
+        message().setValue("Half written");
+        waitForVaadin();
+        aboutLink().click();
+        waitForVaadin();
+
+        assertThat(dialogButton("Discard")).isVisible();
+        dialogButton("Discard").click();
+        waitForVaadin();
+
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
