+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.about.AboutView;
+import com.example.contact.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactFormBrowserlessTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Object> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(phone()).setValue(phoneValue);
+        test(message()).setValue(messageValue);
+    }
+
+    @Test
+    void contactView_initialState() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled(), "Send should be enabled initially");
+        assertTrue($(RouterLink.class).withText("About").exists());
+    }
+
+    @Test
+    void aboutLink_navigatesToAboutView() {
+        navigate(ContactView.class);
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyForm_send_marksNameEmailAndMessageInvalid() {
+        navigate(ContactView.class);
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+
+        assertFalse($(Notification.class).exists(), "no notification");
+        assertEquals(0, test(grid()).size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void invalidEmail_isReported() {
+        navigate(ContactView.class);
+        fill("Alice", "not-an-email", "", "Hello");
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals(0, test(grid()).size());
+        assertEquals("Alice", name().getValue(), "input is kept");
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "x".repeat(501));
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters",
+                message().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void exactly500Characters_isSent() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "x".repeat(500));
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void phoneOnly_isEnough() {
+        navigate(ContactView.class);
+        fill("Alice", "", "+358 40 1234567", "Call me");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_send_notifiesClearsAndDisablesSend() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "Hello there");
+        test(send()).click();
+
+        assertTrue(test($(Notification.class).last()).getText()
+                .contains("Message sent"));
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Alice", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+
+        assertFalse(send().isEnabled(), "Send is disabled after sending");
+
+        test(name()).setValue("Bob");
+        assertTrue(send().isEnabled(), "editing re-enables Send");
+    }
+
+    @Test
+    void enter_sendsTheMessage() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "Sent with Enter");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Sent with Enter", test(grid()).getCellText(0, 1));
+    }
+
+    @Test
+    void messages_areListedNewestFirst() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "First");
+        test(send()).click();
+        fill("Bob", "bob@example.com", "", "Second");
+        test(send()).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Bob", test(grid()).getCellText(0, 0));
+        assertEquals("Alice", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void sentMessages_surviveLeavingTheView() {
+        navigate(ContactView.class);
+        fill("Alice", "alice@example.com", "", "Hello there");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Alice", test(grid()).getCellText(0, 0));
+
+        assertEquals("", name().getValue(), "a new visit starts empty");
+        assertTrue(send().isEnabled(), "an untouched form can be sent");
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        navigate(ContactView.class);
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists(), "no dialog for an empty form");
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void filledForm_keepEditing_staysOnTheView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Alice");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Alice", name().getValue());
+        assertFalse($(Dialog.class).exists() && $(Dialog.class).single()
+                .isOpened(), "dialog is closed");
+    }
+
+    @Test
+    void filledForm_discard_leavesTheView() {
+        navigate(ContactView.class);
+        test(message()).setValue("Half written");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void filledForm_navigationFromElsewhere_alsoAsks() {
+        navigate(ContactView.class);
+        test(phone()).setValue("123456");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
